  _ = `Tombol Aktivasi Menu - Trigger Kanan (Tekan Penuh)`,
  _ = `Item Menu Sentuh yang disorot akan aktif saat tombol Trigger Kanan ditekan.`,
  _ = `Tombol Aktivasi Menu - Trigger Kiri (Tekan Ringan)`,
  _ = `Item Menu Sentuh yang disorot akan aktif saat Trigger Kiri sedikit ditekan.`,
  _ = `Tombol Aktivasi Menu - Trigger Kanan (Tekan Ringan)`,
  _ = `Item Menu Sentuh yang disorot akan aktif saat Trigger Kanan sedikit ditekan.`,
  _ = `Tombol Aktivasi Menu - A`,
  _ = `Item Menu Sentuh yang disorot akan aktif saat tombol A ditekan.`,
  _ = `Tombol Aktivasi Menu - B`,
  _ = `Item Menu Sentuh yang disorot akan aktif saat tombol B ditekan.`,
  _ = `Tombol Aktivasi Menu - X`,
  _ = `Item Menu Sentuh yang disorot akan aktif saat tombol X ditekan.`,
