  _ = `Tombol Aktifkan Giroskop - Bumper Kiri`,
  _ = `Input giroskop hanya akan aktif saat tombol Bumper Kiri ditekan.`,
  _ = `Tombol Aktifkan Giroskop - Grip Kanan`,
  _ = `Input giroskop hanya akan aktif saat tombol Grip Kanan ditekan.`,
  _ = `Tombol Aktifkan Giroskop - Grip Kiri`,
  _ = `Input giroskop hanya akan aktif saat tombol Grip Kiri ditekan.`,
  _ = `Tombol Aktifkan Giroskop - Trigger Kiri (Tekan Penuh)`,
  _ = `Input giroskop hanya akan aktif saat tombol Trigger Kiri ditekan.`,
  _ = `Tombol Aktifkan Giroskop - Trigger Kanan (Tekan Penuh)`,
  _ = `Input giroskop hanya akan aktif saat tombol Trigger Kanan ditekan.`,
  _ = `Tombol Aktifkan Giroskop - Trigger Kiri (Tekan Ringan)`,
  _ = `Input giroskop hanya akan aktif saat Trigger Kiri sedikit ditekan.`,
  _ = `Tombol Aktifkan Giroskop - Trigger Kanan (Tekan Ringan)`,
  _ = `Input giroskop hanya akan aktif saat Trigger Kanan sedikit ditekan.`,
  _ = `Tombol Aktifkan Giroskop - A`,
  _ = `Input giroskop hanya akan aktif saat tombol A ditekan.`,
  _ = `Tombol Aktifkan Giroskop - B`,
  _ = `Input giroskop hanya akan aktif saat tombol B ditekan.`,
  _ = `Tombol Aktifkan Giroskop - X`,
  _ = `Input giroskop hanya akan aktif saat tombol X ditekan.`,
  _ = `Tombol Aktifkan Giroskop - Y`,
  _ = `Input giroskop hanya akan aktif saat tombol Y ditekan.`,
  _ = `Tombol Aktifkan Giroskop - Silang`,
  _ = `Input giroskop hanya akan aktif saat tombol Silang ditekan.`,
  _ = `Tombol Aktifkan Giroskop - Lingkaran`,
  _ = `Input giroskop hanya akan aktif saat tombol Lingkaran ditekan.`,
  _ = `Tombol Aktifkan Giroskop - Kotak`,
  _ = `Input giroskop hanya akan aktif saat tombol Kotak ditekan.`,
  _ = `Tombol Aktifkan Giroskop - Segitiga`,
  _ = `Input giroskop hanya akan aktif saat tombol Segitiga ditekan.`,
  _ = `Tombol Aktifkan Giroskop - Stik Kiri (Klik)`,
  _ = `Input giroskop hanya akan aktif saat Stik Kiri diklik.`,
  _ = `Tombol Aktifkan Giroskop - Stik Kanan (Klik)`,
  _ = `Input giroskop hanya akan aktif saat Stik Kanan diklik.`,
  _ = `Tombol Aktifkan Giroskop - Tombol Capture (Klik)`,
  _ = `Input giroskop hanya akan aktif saat tombol Capture diklik.`,
  _ = `Tombol Aktifkan Giroskop - Trigger Kanan`,
  _ = `Input giroskop hanya akan aktif saat tombol Trigger Kanan diklik.`,
  _ = `Tombol Aktifkan Giroskop - Trigger Kiri`,
